import * as THREE from 'three';
import {OrbitControls} from '../../assets/OrbitControls.js';
const $=id=>document.getElementById(id),vp=$('viewport'),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,3000);camera.up.set(0,0,1);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;vp.appendChild(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=10;controls.maxDistance=2000;
scene.add(new THREE.HemisphereLight(0xffffff,0x9ca3af,2));for(const [x,y,z,p] of [[0,-80,150,3],[-70,100,60,2]]){const light=new THREE.DirectionalLight(0xffffff,p);light.position.set(x,y,z);scene.add(light)}
const grid=new THREE.GridHelper(500,50,0xd1d5db,0xe5e7eb);grid.rotation.x=Math.PI/2;grid.position.z=-41.2;scene.add(grid);
const objects=[],hidden=new Set();let data,playing=false,mode='motion',phase=0,last=0,selected=null;
const ramp=(v,a,b)=>Math.max(0,Math.min(1,(v-a)/(b-a)));
function stop(){playing=false;$('play').textContent='Play actuation'}
function closeMenu(){$('partMenu').hidden=true}
function select(o){selected=o;$('partSelect').value=o?.userData.name||'';$('hideSelected').disabled=!o||!o.visible}
function hide(o){if(o){hidden.add(o.userData.name);select(null)}closeMenu();update()}
function showAll(){hidden.clear();$('fixture').checked=true;closeMenu();update()}
function update(){if(!data)return;const dx=+$('travel').value-20,e=mode==='explode'?+$('explosion').value/100:0,pivot=new THREE.Vector3(...data.axisOrigin),axis=new THREE.Vector3(1,0,0),theta=-dx*2*Math.PI/data.lead;
 for(const o of objects){const p=o.userData;o.position.set(0,0,0);o.quaternion.identity();
  if(mode==='explode'){if(p.group==='drive')o.position.y=-65*ramp(e,.3,1);if(p.group==='mount_bolts')o.position.set(0,-40*ramp(e,.15,.3),15*ramp(e,0,.15))}
  else if(p.group==='rack')o.position.x=dx;
  else if(p.rotating){o.quaternion.setFromAxisAngle(axis,theta);o.position.copy(pivot).sub(pivot.clone().applyQuaternion(o.quaternion))}
  else if(p.spinAxis){const c=new THREE.Vector3(...p.spinCenter);o.quaternion.setFromAxisAngle(new THREE.Vector3(...p.spinAxis),p.spinSign*dx/8);o.position.copy(c).sub(c.clone().applyQuaternion(o.quaternion))}
  o.visible=!hidden.has(p.name)&&(p.name!=='Open guide fixture'||$('fixture').checked);o.children[0].visible=$('edges').checked;
 }
 $('travelValue').textContent=(dx+20).toFixed(2)+' mm';$('explodeValue').textContent=Math.round(e*100)+'%';$('modeBadge').textContent=mode==='explode'?'MODULE SEPARATION':playing?'ACTUATING':'EXPERIMENT';$('status').textContent=hidden.size?hidden.size+' hidden parts':'';
 $('hideSelected').disabled=!selected||!selected.visible;
}
function fit(direction=new THREE.Vector3(1,-1.4,1)){if(!(direction instanceof THREE.Vector3))direction=new THREE.Vector3(1,-1.4,1);direction.normalize();const bb=new THREE.Box3();for(const o of objects)if(o.visible)bb.expandByObject(o);if(bb.isEmpty())return;const center=bb.getCenter(new THREE.Vector3()),size=bb.getSize(new THREE.Vector3());let d=size.length()/2/Math.sin(THREE.MathUtils.degToRad(camera.fov/2));if(camera.aspect<1)d/=camera.aspect;camera.position.copy(center).addScaledVector(direction,d*1.05);controls.target.copy(center);controls.update()}
function setMode(m){stop();mode=m;$('motionControls').hidden=m!=='motion';$('explosionControls').hidden=m!=='explode';for(const n of ['motion','explode']){$(n+'Tab').classList.toggle('active',n===m);$(n+'Tab').setAttribute('aria-selected',n===m)}update();fit()}
$('driveVariant').onchange=()=>{if($('driveVariant').value==='spur')location.href='../../?motor=nema17&stroke=40'};
$('motionTab').onclick=()=>setMode('motion');$('explodeTab').onclick=()=>setMode('explode');$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause actuation':'Play actuation';phase=Math.asin((+$('travel').value-20)/20);update()};$('travel').oninput=()=>{stop();update()};$('explosion').oninput=update;
for(const id of ['fixture','edges'])$(id).onchange=update;
$('partSelect').onchange=()=>select(objects.find(o=>o.userData.name===$('partSelect').value));$('hideSelected').onclick=()=>hide(selected);$('showAll').onclick=showAll;
$('iso').onclick=fit;$('fit').onclick=fit;$('top').onclick=()=>fit(new THREE.Vector3(0,-.001,1));$('mesh').onclick=()=>{setMode('motion');$('fixture').checked=false;update();controls.target.set(0,16,17);camera.position.set(30,-24,64);controls.update()};$('reset').onclick=()=>{showAll();$('travel').value=20;$('explosion').value=0;$('edges').checked=false;select(null);setMode('motion')};
const ray=new THREE.Raycaster();function pick(e){const r=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2),camera);return ray.intersectObjects(objects.filter(o=>o.visible),false)[0]?.object}
let start;renderer.domElement.addEventListener('pointerdown',e=>{start=[e.clientX,e.clientY];closeMenu()});renderer.domElement.addEventListener('pointerup',e=>{if(e.button===0&&start&&Math.hypot(e.clientX-start[0],e.clientY-start[1])<5)select(pick(e))});renderer.domElement.addEventListener('contextmenu',e=>{e.preventDefault();const o=pick(e);select(o);$('menuPartName').textContent=o?.userData.name||'Parts';$('menuHide').hidden=!o;const menu=$('partMenu');menu.hidden=false;menu.style.left=Math.min(e.clientX,innerWidth-menu.offsetWidth-8)+'px';menu.style.top=Math.min(e.clientY,innerHeight-menu.offsetHeight-8)+'px';(o?$('menuHide'):$('menuShowAll')).focus()});$('menuHide').onclick=()=>hide(selected);$('menuShowAll').onclick=showAll;document.addEventListener('pointerdown',e=>{if(!$('partMenu').contains(e.target))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
new ResizeObserver(()=>{camera.aspect=vp.clientWidth/vp.clientHeight;camera.updateProjectionMatrix();renderer.setSize(vp.clientWidth,vp.clientHeight,false);if(data)fit()}).observe(vp);
for(const n of [1,2,4,8,16]){$('resolutionRows').insertAdjacentHTML('beforeend',`<tr><th>${n===1?'Full step':`1/${n} step`}</th><td>${(Math.PI*2/200/n).toFixed(6)}</td><td>${(Math.PI*2/200/n*1000).toFixed(3)}</td></tr>`)}
try{const response=await fetch('assembly.json.gz');if(!response.ok)throw Error('Model download failed');data=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();for(const p of data.parts){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(p.vertices.flat(),3));geometry.setIndex(p.triangles.flat());geometry.computeVertexNormals();const mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:p.color,metalness:p.printed?.05:.3,roughness:p.printed?.72:.42}));mesh.userData=p;const edges=new THREE.LineSegments(new THREE.EdgesGeometry(geometry,32),new THREE.LineBasicMaterial({color:0x475569,transparent:true,opacity:.4}));mesh.add(edges);objects.push(mesh);scene.add(mesh);const option=document.createElement('option');option.value=option.textContent=p.name;$('partSelect').appendChild(option)}$('loading').hidden=true;update();fit();window.wormViewer={objects,data,scene,camera,controls,renderer,update,fit};const report=await(await fetch('validation.json')).json();$('proof').innerHTML=`<div><strong>${report.mesh.matched_nominal_max_overlap_mm3.toFixed(4)} mm³</strong><span>Largest nominal mesh interference</span></div><div><strong>${report.motion_samples} positions</strong><span>Full-stroke solid checks</span></div><div><strong>${report.module_separation_samples} poses</strong><span>Staged module separation</span></div>`;$('checkSummary').textContent=report.passed?'Sampled geometry checks passed. The original straight rack interferes with the worm; the matched rack clears at nominal size. Oversized compliant flanks maintain geometric engagement throughout the stroke.':'Checks identified unresolved geometry issues. See the report before printing.';
}catch(error){if(objects.length){$('checkSummary').textContent='Check report unavailable: '+error.message}else{$('loading').hidden=false;$('loading').textContent='Could not load the experiment. '+error.message}console.error(error)}
function frame(now){const dt=last?Math.min(.05,(now-last)/1000):0;last=now;if(playing){phase+=dt*.4;$('travel').value=20+20*Math.sin(phase);update()}controls.update();renderer.render(scene,camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);
